  up.sort(function(x,y){return x.dd-y.dd||String(x.a.delivery_time||'').localeCompare(String(y.a.delivery_time||''));});
  var openT=0,doneT=0,dueToday=0,overdue=0,byStn={};
  for(var t=0;t<tasks.length;t++){var ta=tasks[t].answers||{};var td=dayDiff(ta.due_date);var stn=STN.indexOf(ta.station)!==-1?ta.station:'prep';
    (byStn[stn]=byStn[stn]||{done:0,total:0}).total++;
