  else{var open=false,lastD=null;
    for(var u=0;u<Math.min(7,up.length);u++){var ev=up[u];
      if(ev.dd!==lastD||!open){if(open)upHtml+='</div>';upHtml+='<div class="day"><div class="day-h">'+h(dayLbl(ev.dd,ev.a.event_date))+'</div>';open=true;lastD=ev.dd;}
      var g=num(ev.a.guest_count);var cl=refName(cn,ev.a.client);
      upHtml+='<div class="sch"><span class="sch-t num">'+(ev.a.delivery_time?h(fmtTime(ev.a.delivery_time)):'\u2014')+'</span><div class="row-main"><div class="row-title">'+h(ev.a.event_name||'Catering job')+'</div><div class="row-sub">'+(cl?h(cl)+' \u00b7 ':'')+h(labelFor(svMap,ev.a.service_type))+(g>0?' \u00b7 '+fmtInt(g)+' guests':'')+'</div></div><div class="row-r">'+pill(labelFor(stMap,ev.a.status),PKJ[ev.a.status]||'neutral')+'</div></div>';}
