  html+=sec('Kitchen & road')+'<div class="grid g11">'+panel('Production completion',pcHtml,fT?'form/'+fT.formId+'/responses':'')+panel(enroute>0?'On the road \u00b7 '+fmtInt(enroute)+' en route':'Dispatch board',dsHtml,fD?'form/'+fD.formId+'/responses':'')+'</div>';
